CREATE TABLE IF NOT EXISTS public.duo_match_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), couple_id uuid NOT NULL REFERENCES public.couples(id) ON DELETE CASCADE, city_slug text NOT NULL REFERENCES public.cities(slug), created_by uuid NOT NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','completed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS duo_match_sessions_couple_created_idx ON public.duo_match_sessions(couple_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.duo_match_candidates (session_id uuid NOT NULL REFERENCES public.duo_match_sessions(id) ON DELETE CASCADE, place_slug text NOT NULL REFERENCES public.places(slug) ON DELETE CASCADE, position smallint NOT NULL, PRIMARY KEY(session_id, place_slug), UNIQUE(session_id, position));
CREATE TABLE IF NOT EXISTS public.duo_match_votes (session_id uuid NOT NULL, place_slug text NOT NULL, user_id uuid NOT NULL, liked boolean NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id, place_slug, user_id), FOREIGN KEY(session_id, place_slug) REFERENCES public.duo_match_candidates(session_id, place_slug) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS duo_match_votes_session_idx ON public.duo_match_votes(session_id, user_id);
ALTER TABLE public.duo_match_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.duo_match_candidates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.duo_match_votes ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.duo_match_sessions, public.duo_match_candidates, public.duo_match_votes TO authenticated;
CREATE POLICY duo_match_sessions_member_access ON public.duo_match_sessions FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.couple_members cm WHERE cm.couple_id = duo_match_sessions.couple_id AND cm.user_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.couple_members cm WHERE cm.couple_id = duo_match_sessions.couple_id AND cm.user_id = auth.uid()));
CREATE POLICY duo_match_candidates_member_access ON public.duo_match_candidates FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.duo_match_sessions s JOIN public.couple_members cm ON cm.couple_id = s.couple_id WHERE s.id = duo_match_candidates.session_id AND cm.user_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.duo_match_sessions s JOIN public.couple_members cm ON cm.couple_id = s.couple_id WHERE s.id = duo_match_candidates.session_id AND cm.user_id = auth.uid()));
CREATE POLICY duo_match_votes_member_read ON public.duo_match_votes FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.duo_match_sessions s JOIN public.couple_members cm ON cm.couple_id=s.couple_id WHERE s.id=duo_match_votes.session_id AND cm.user_id=auth.uid()));
CREATE POLICY duo_match_votes_member_insert ON public.duo_match_votes FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.duo_match_sessions s JOIN public.couple_members cm ON cm.couple_id=s.couple_id WHERE s.id=duo_match_votes.session_id AND cm.user_id=auth.uid()));
CREATE POLICY duo_match_votes_member_update ON public.duo_match_votes FOR UPDATE TO authenticated USING (user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.duo_match_sessions s JOIN public.couple_members cm ON cm.couple_id=s.couple_id WHERE s.id=duo_match_votes.session_id AND cm.user_id=auth.uid())) WITH CHECK (user_id=auth.uid());
CREATE POLICY duo_match_votes_member_delete ON public.duo_match_votes FOR DELETE TO authenticated USING (user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.duo_match_sessions s JOIN public.couple_members cm ON cm.couple_id=s.couple_id WHERE s.id=duo_match_votes.session_id AND cm.user_id=auth.uid()));
